{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C53"],
      "claim": "Ivabradine, the closest high-similarity analogue (Morgan 0.6441), has an absolute oral bioavailability of 51.5 ± 17.8% in healthy volunteers after a 7.5 mg oral solution, well above the 20% threshold, and shares the same benzazepinone core and propylamine side chain as the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Ivabradine is almost completely absorbed (~90%) with an oral bioavailability close to 40% in healthy volunteers due to hepatic first-pass metabolism, independently supporting that this chemotype can achieve F ≥ 20% despite first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Donepezil, a dimethoxyaromatic basic amine, has an oral bioavailability of 100% in humans, showing that the dimethoxybenzene and basic amine features do not inherently cause low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine has a mean absolute oral bioavailability of only 4.9% in patients, but its structural similarity to the query is much lower (Morgan 0.3731) and it lacks the lactam/benzazepinone core, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant has an absolute oral bioavailability of 11.2% in healthy subjects, but its similarity to the query is low (Morgan 0.2472) and its amide/isoquinoline framework differs substantially from the query's benzazepinone lactam.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest transferable evidence comes from ivabradine (Morgan 0.6441), which shares the query's benzazepinone core and propylamine side chain and has an absolute oral bioavailability of approximately 40-51% in humans, clearly above the 20% threshold. The low-F analogues tetrabenazine and almorexant are much less similar and have different core scaffolds. The query's indane-for-phenethyl modification is modest and unlikely to reduce F below 20%, so high is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "The effect of replacing ivabradine's dimethoxyphenethyl group with a dimethoxyindanylmethyl group on first-pass metabolism is not directly measured.",
    "No human data for the query's specific lactam/amine combination; some supporting animal data are from different species.",
    "Potential P-gp efflux or CYP-mediated first-pass metabolism of the query is not experimentally characterized."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C53", "C48", "C46"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "ivabradine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C56", "C51", "C55", "C47", "C52"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "tetrabenazine"
    },
    {
      "applicability": "low",
      "card_ids": ["C49", "C50"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "armepavine"
    },
    {
      "applicability": "low",
      "card_ids": ["C54", "C45"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carmegliptin"
    }
  ],
  "revision_action": "flip"
}

